.medal-toast{position:fixed!important;left:50%!important;bottom:112px!important;transform:translateX(-50%)!important;z-index:90!important;min-width:220px!important;max-width:92vw!important;padding:14px 22px!important;border-radius:999px!important;background:#0f172a!important;color:#fff!important;font-size:14px!important;font-weight:800!important;text-align:center!important;opacity:0!important;pointer-events:none!important;transition:opacity .18s ease,transform .18s ease!important}.medal-toast.show{opacity:1!important;pointer-events:auto!important;transform:translateX(-50%) translateY(0)!important}
