<script>
(function(){
  var loggedIn=<?= $userId > 0 ? 'true' : 'false' ?>;
  var csrf=<?= json_encode($csrf, JSON_UNESCAPED_UNICODE) ?>;
  var medals=<?= json_encode($clientMedals, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>;
  var slots=<?= json_encode($slotValues, JSON_UNESCAPED_UNICODE) ?>.map(function(x){return x?parseInt(x,10):null;}).slice(0,5);
  while(slots.length<5)slots.push(null);
  var tab='all', quality='all', page=1, pageSize=18, drag=null, saving=false;
  var qualities=<?= json_encode(array_merge([['code'=>'all','name'=>'全部品质','color'=>'#2563eb','badge_count'=>count($medals ?? [])]], array_map(function($q){ return ['code'=>(string)($q['code'] ?? ''),'name'=>(string)($q['name'] ?? ''),'color'=>preg_match('/^#[0-9a-fA-F]{6}$/', (string)($q['color'] ?? '')) ? (string)$q['color'] : '#64748b','badge_count'=>(int)($q['badge_count'] ?? 0)]; }, $qualities ?? [])), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>;
  var slotBox=document.getElementById('medalSlots'), grid=document.getElementById('medalGrid'), pager=document.getElementById('libraryPager'), qualityTabs=document.getElementById('qualityTabs'), toast=document.getElementById('medalToast');
  function byId(id){return medals.find(function(m){return parseInt(m.id,10)===parseInt(id,10);})||null;}
  function esc(s){return String(s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c];});}
  function icon(m){return m&&m.icon?'<img src="'+esc(m.icon)+'" alt="" loading="lazy">':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="8" r="4"/><path d="M8.5 12.5 7 21l5-3 5 3-1.5-8.5"/></svg>';}
  function toastMsg(msg,bad){toast.textContent=msg;toast.style.background=bad?'rgba(153,27,27,.94)':'rgba(15,23,42,.92)';toast.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(function(){toast.classList.remove('show');},1800);}
  function cleanSlots(arr){var out=[];arr.forEach(function(id){id=parseInt(id||0,10); if(id>0 && out.indexOf(id)===-1) out.push(id);}); while(out.length<5)out.push(null); return out.slice(0,5);}
  function save(action){if(!loggedIn)return;var oldSlots=slots.slice();slots=cleanSlots(slots);document.getElementById('equippedCount').textContent=slots.filter(Boolean).length;if(saving)return; saving=true; var fd=new FormData();fd.append('_csrf_token',csrf);fd.append('_action','layout');fd.append('slots',JSON.stringify(slots.filter(Boolean)));fetch('/index.php?path=medals',{method:'POST',body:fd,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.json().catch(function(){return {ok:false,error:'保存失败'};});}).then(function(d){if(!d.ok)throw new Error(d.error||'保存失败'); medals.forEach(function(m){var i=slots.indexOf(m.id);m.equipped=i!==-1;m.slot=i+1;}); render(); var added=[];var removed=[];for(var i=0;i<5;i++){var o=oldSlots[i]||null;var n=slots[i]||null;if(o!==n){if(n&&oldSlots.indexOf(n)===-1){var m=byId(n);if(m)added.push(m.name);}if(o&&slots.indexOf(o)===-1){var m=byId(o);if(m)removed.push(m.name);}}}var msg='已保存展示位';if(added.length===1&&removed.length===0)msg='已装备「'+added[0]+'」';else if(removed.length===1&&added.length===0)msg='已卸下「'+removed[0]+'」';else if(added.length>0&&removed.length===0)msg='已装备 '+added.length+' 个勋章';else if(removed.length>0&&added.length===0)msg='已卸下 '+removed.length+' 个勋章';toastMsg(msg);}).catch(function(e){toastMsg(e.message||'保存失败',true);}).finally(function(){saving=false;});}
  function renderSlots(){slotBox.innerHTML='';slots=cleanSlots(slots);slots.forEach(function(id,i){var m=byId(id);var slot=document.createElement('div');slot.className='medal-slot'+(m?' is-filled':'');slot.dataset.slot=i;slot.innerHTML='<span class="slot-index">'+(i+1)+'</span>'+(m?'<button class="slot-medal" type="button" draggable="true" data-id="'+m.id+'" title="'+esc(m.name)+'">'+icon(m)+'</button><button class="slot-remove" type="button" data-remove="'+i+'" aria-label="卸下"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6 6 18M6 6l12 12"/></svg></button>':'<div class="slot-empty"><span></span>空位</div>');slotBox.appendChild(slot);});document.getElementById('equippedCount').textContent=slots.filter(Boolean).length;}
  function renderQualityTabs(){if(!qualityTabs)return;qualityTabs.style.display=tab==='all'?'flex':'none';qualityTabs.innerHTML=qualities.map(function(q){var key=q.code||'all';var count=medals.filter(function(m){return !m.owned&&(key==='all'||m.level===key);}).length;return '<button class="quality-tab '+(quality===key?'active':'')+'" type="button" data-quality="'+esc(key)+'" style="--quality-color:'+esc(q.color||'#2563eb')+'">'+esc(q.name||key)+' <span>'+count+'</span></button>';}).join('');}
  function filteredList(){return medals.filter(function(m){if(tab==='mine')return m.owned;if(m.owned)return false;if(quality!=='all'&&m.level!==quality)return false;return true;});}
  function renderPager(total){if(!pager)return;var pages=Math.max(1,Math.ceil(total/pageSize));if(page>pages)page=pages;pager.style.display=pages>1?'flex':'none';var html='<button class="page-btn" type="button" data-page="prev" '+(page<=1?'disabled':'')+'>上一页</button>';for(var i=1;i<=pages;i++){html+='<button class="page-btn '+(i===page?'active':'')+'" type="button" data-page="'+i+'">'+i+'</button>';}html+='<button class="page-btn" type="button" data-page="next" '+(page>=pages?'disabled':'')+'>下一页</button>';pager.innerHTML=html;}
  function renderGrid(){var list=filteredList();var total=list.length;renderPager(total);var start=(page-1)*pageSize;list=list.slice(start,start+pageSize);grid.innerHTML=list.map(function(m){var cls='library-card '+(m.owned?'owned can-drag':'locked')+(slots.indexOf(m.id)!==-1?' equipped':'');return '<article class="'+cls+'" data-id="'+m.id+'" style="--quality-color:'+esc(m.level_color||'#64748b')+'"><button class="library-medal" type="button" '+(m.owned&&loggedIn?'draggable="true"':'')+' data-id="'+m.id+'" title="'+esc(m.name)+'">'+icon(m)+'</button></article>';}).join('') || '<div class="library-empty">'+(tab==='mine'?'暂无已获得勋章':'当前品质暂无勋章')+'</div>';}
  function render(){renderSlots();renderQualityTabs();renderGrid();}
  function openModal(id){var m=byId(id); if(!m)return;document.getElementById('modalIcon').innerHTML=icon(m);document.getElementById('modalMedalName').textContent=m.name;document.getElementById('modalDesc').textContent=m.description||'暂无勋章说明';document.getElementById('modalOwned').textContent=m.owned?(m.equipped?'状态：已佩戴':'状态：已拥有'):'状态：未获得';document.getElementById('modalRule').textContent=m.rule||'由管理员手动发放';var actions=document.getElementById('modalActions');actions.innerHTML='';if(loggedIn&&m.owned){var idx=slots.indexOf(m.id);var btn=document.createElement('button');btn.className='modal-action '+(idx!==-1?'danger':'');btn.type='button';btn.textContent=idx!==-1?'卸下勋章':'佩戴到空位';btn.onclick=function(){if(idx!==-1){slots[idx]=null;}else{var empty=slots.indexOf(null);if(empty===-1){toastMsg('展示位已满，请先卸下一个勋章',true);return;}slots[empty]=m.id;}closeModal();save();render();};actions.appendChild(btn);}else if(loggedIn&&!m.owned&&m.obtain_method==='free'){var fb=document.createElement('button');fb.className='modal-action';fb.type='button';fb.textContent='免费领取';fb.onclick=function(){medalAction('claim_badge',m.id);};actions.appendChild(fb);}else if(loggedIn&&!m.owned&&m.obtain_method==='shop'){var sb=document.createElement('button');sb.className='modal-action';sb.type='button';sb.disabled=!m.can_afford;sb.textContent=m.can_afford?('购买 '+(m.price_label||'')):'余额不足';sb.onclick=function(){if(m.can_afford&&confirm('确认花费 '+(m.price_label||'')+' 购买该勋章？'))medalAction('buy_badge',m.id);};actions.appendChild(sb);}else if(!loggedIn){var a=document.createElement('a');a.className='modal-action';a.href='/index.php?path=login&redirect='+encodeURIComponent('/index.php?path=medals');a.textContent='登录后管理';actions.appendChild(a);}document.getElementById('medalModal').classList.add('open');document.getElementById('medalModal').setAttribute('aria-hidden','false');}
  function medalAction(act,bid){var fd=new FormData();fd.append('_csrf_token',csrf);fd.append('_action',act);fd.append('badge_id',bid);fetch('/index.php?path=decoration&tab=medals',{method:'POST',body:fd,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.json().catch(function(){return{ok:false,error:'操作失败'};});}).then(function(d){if(!d.ok)throw new Error(d.error||'操作失败');var m=byId(bid);if(m)m.owned=true;closeModal();render();toastMsg(act==='claim_badge'?'领取成功':'购买成功');}).catch(function(e){toastMsg(e.message||'操作失败',true);});}
  function closeModal(){var modal=document.getElementById('medalModal');modal.classList.remove('open');modal.setAttribute('aria-hidden','true');}
  document.querySelectorAll('.medal-tab').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('.medal-tab').forEach(function(x){x.classList.remove('active');});b.classList.add('active');tab=b.dataset.tab;quality='all';page=1;render();});});
  document.addEventListener('click',function(e){var q=e.target.closest('#qualityTabs .quality-tab');if(q){quality=q.dataset.quality||'all';page=1;render();return;}var pg=e.target.closest('.page-btn');if(pg&&!pg.disabled){var total=filteredList().length,pages=Math.max(1,Math.ceil(total/pageSize));var val=pg.dataset.page;if(val==='prev')page=Math.max(1,page-1);else if(val==='next')page=Math.min(pages,page+1);else page=parseInt(val,10)||1;renderGrid();return;}var close=e.target.closest('[data-modal-close]');if(close){closeModal();return;}var remove=e.target.closest('[data-remove]');if(remove){slots[parseInt(remove.dataset.remove,10)]=null;save();render();return;}var medal=e.target.closest('.slot-medal,.library-medal');if(medal){openModal(parseInt(medal.dataset.id,10));}});
  document.addEventListener('dragstart',function(e){var el=e.target.closest('.slot-medal,.library-medal');if(!el||!loggedIn)return;var id=parseInt(el.dataset.id,10), m=byId(id);if(!m||!m.owned){e.preventDefault();return;}drag={id:id,fromSlot:el.closest('.medal-slot')?parseInt(el.closest('.medal-slot').dataset.slot,10):null};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(id));});
  document.addEventListener('dragover',function(e){var slot=e.target.closest('.medal-slot');if(slot){e.preventDefault();slot.classList.add('is-over');}});
  document.addEventListener('dragleave',function(e){var slot=e.target.closest('.medal-slot');if(slot)slot.classList.remove('is-over');});
  document.addEventListener('drop',function(e){var slot=e.target.closest('.medal-slot');document.querySelectorAll('.is-over').forEach(function(x){x.classList.remove('is-over');});if(!drag)return;if(slot){e.preventDefault();var target=parseInt(slot.dataset.slot,10);var existing=slots[target];var old=slots.indexOf(drag.id);if(old!==-1)slots[old]=null;if(drag.fromSlot!==null&&existing){slots[drag.fromSlot]=existing;}slots[target]=drag.id;save();render();drag=null;}});
  document.addEventListener('keydown',function(e){if(e.key==='Escape')closeModal();});
  render();
})();
</script>
